    [FunctionalFact]
    public async Task GivenActualRecipientProtectionRotationAfterNativeValidation_WhenMoving_ThenStaleEvidenceConflictsAndFreshRetrySucceeds()
    {
        using var owner=new ProtectionFixture();using var client=new ProtectionFixture();var s=await ProfileSetup.Create(fixture,owner);var recipient=await ProfileSetup.Create(fixture,client);var a=await AssociationSetup.Items(fixture,s);var target=await Folder(s);await Members(s,a.Collection,[],[a.Folder.Id]);await AssociationSetup.Grant(fixture,s,owner,recipient,client,a.Collection);
        var change=new ProtectionChange(recipient.AccountId,1,1,"rotate-content",client.Rewrap(),[new("account",recipient.AccountId,1,ProfileSetup.Envelope(2))]);var raw=Bytes(change);var challenge=(await new VaultProtectionStore(fixture).ChallengeAsync(recipient.Actor,"change-protection",ProtocolBinary.Encode(SHA256.HashData(raw)),default)).Data!;
        var before=await Snapshot(s);var hook=new BeforeWrite(async()=>Assert.Null((await new VaultProtectionChangeStore(fixture).ChangeAsync(new(recipient.Actor,recipient.Verifier,challenge.ChallengeId,client.Sign(challenge),raw,change),default)).Error));
        Assert.Equal("revision_conflict",(await new FolderMoveStore(new ProfileSetup.Factory(fixture,hook)).MoveAsync(new(s.Actor,s.Verifier,target.PublicId,1,a.Folder.PublicId),default)).Error);Assert.Equal(before,await Snapshot(s));await Success(target,a.Folder,null,a.Folder,await Move(s,target,a.Folder.PublicId));
    }

    [FunctionalFact]
    public async Task GivenActualOwnerRotationWaitsBehindMove_WhenMoveCommits_ThenStaleInventoryConflictsWithoutConsumingProof()
    {
        using var owner=new ProtectionFixture();var s=await ProfileSetup.Create(fixture,owner);var from=await Folder(s);var to=await Folder(s);var target=await Folder(s,from.Id);var change=new ProtectionChange(s.AccountId,1,1,"rotate-content",owner.Rewrap(),[new("account",s.AccountId,1,ProfileSetup.Envelope(2)),new("folder",target.PublicId,1,ProfileSetup.Envelope(2)),new("folder",from.PublicId,1,ProfileSetup.Envelope(2)),new("folder",to.PublicId,1,ProfileSetup.Envelope(2))]);var raw=Bytes(change);var challenge=(await new VaultProtectionStore(fixture).ChallengeAsync(s.Actor,"change-protection",ProtocolBinary.Encode(SHA256.HashData(raw)),default)).Data!;
        var reached=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var release=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var blocked=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);using var ct=new CancellationTokenSource(TimeSpan.FromSeconds(20));var move=new FolderMoveStore(new ProfileSetup.Factory(fixture,new BeforeWrite(async()=>{reached.TrySetResult();await release.Task.WaitAsync(ct.Token);}))).MoveAsync(new(s.Actor,s.Verifier,target.PublicId,1,to.PublicId),ct.Token);await reached.Task.WaitAsync(TimeSpan.FromSeconds(10));var rotation=new VaultProtectionChangeStore(new ProfileSetup.Factory(fixture,new Signal(blocked,"account"))).ChangeAsync(new(s.Actor,s.Verifier,challenge.ChallengeId,owner.Sign(challenge),raw,change),ct.Token);
        try{await blocked.Task.WaitAsync(TimeSpan.FromSeconds(10));Assert.False(rotation.IsCompleted);}finally{release.TrySetResult();}await Success(target,to,from,to,await move);Assert.Equal("revision_conflict",(await rotation).Error);await using var db=fixture.CreateContext();Assert.False((await db.VaultUnlockChallenges.SingleAsync(x=>x.PublicId==challenge.ChallengeId)).Consumed);Assert.Equal(1,(await db.VaultProtections.SingleAsync(x=>x.AccountId==s.InternalId)).Revision);
    }

    [FunctionalTheory][InlineData(false)][InlineData(true)]
    public async Task GivenActualOwnerRotationBeforeOrAfterMove_WhenReloading_ThenRetainCurrentParentAndRespectEpochRevisionAndHandle(bool rotateFirst)
    {
        using var owner=new ProtectionFixture();var s=await ProfileSetup.Create(fixture,owner);var from=await Folder(s);var to=await Folder(s);var target=await Folder(s,from.Id);
        if(!rotateFirst){await Success(target,to,from,to,await Move(s,target,to.PublicId));target=await Row(target.Id);from=await FolderRow(from.Id);to=await FolderRow(to.Id);}
        var change=new ProtectionChange(s.AccountId,1,1,"rotate-content",owner.Rewrap(),[new("account",s.AccountId,1,ProfileSetup.Envelope(2)),new("folder",target.PublicId,target.Revision,ProfileSetup.Envelope(2)),new("folder",from.PublicId,from.Revision,ProfileSetup.Envelope(2)),new("folder",to.PublicId,to.Revision,ProfileSetup.Envelope(2))]);var raw=Bytes(change);var challenge=(await new VaultProtectionStore(fixture).ChallengeAsync(s.Actor,"change-protection",ProtocolBinary.Encode(SHA256.HashData(raw)),default)).Data!;Assert.Null((await new VaultProtectionChangeStore(fixture).ChangeAsync(new(s.Actor,s.Verifier,challenge.ChallengeId,owner.Sign(challenge),raw,change),default)).Error);
        Assert.Equal("vault_access_denied",(await Move(s,target,to.PublicId,1)).Error);var row=await Row(target.Id);Assert.Equal(rotateFirst?from.Id:to.Id,row.ParentFolderId);Assert.Equal(2,JsonSerializer.Deserialize<EncryptedEnvelope>(row.Envelope,ProtectionFixture.Json)!.KeyEpoch);
        if(rotateFirst){var verifier=Convert.ToHexStringLower(RandomNumberGenerator.GetBytes(32));await using(var db=fixture.CreateContext()){var account=await db.Accounts.SingleAsync(x=>x.Id==s.InternalId);db.VaultAccessSessions.Add(new(){AccountId=s.InternalId,HandleVerifier=verifier,IssuedAt=DateTimeOffset.UtcNow.AddMinutes(-1),ExpiresAt=DateTimeOffset.UtcNow.AddHours(1),PolicyRevision=account.PolicyRevision,RevocationGeneration=account.RevocationGeneration});await db.SaveChangesAsync();}s=s with{Verifier=verifier};var before=await Snapshot(s);Assert.Equal("revision_conflict",(await Move(s,row,to.PublicId,1)).Error);Assert.Equal(before,await Snapshot(s));await Success(row,to,await FolderRow(from.Id),await FolderRow(to.Id),await Move(s,row,to.PublicId,row.Revision));}
    }

    [FunctionalTheory][InlineData(false,false)][InlineData(false,true)][InlineData(true,false)][InlineData(true,true)]
    public async Task GivenSequenceExhaustionOrRegressionAtTargetOrParent_WhenMoving_ThenRollbackAllStructuralChanges(bool parent,bool regression)
    {
        using var owner=new ProtectionFixture();var s=await ProfileSetup.Create(fixture,owner);var from=await Folder(s);var to=await Folder(s);var target=await Folder(s,from.Id);var before=await Snapshot(s);await using var db=fixture.CreateContext();var previous=await db.Database.SqlQuery<long>($"SELECT nextval('cerberus.server_sequence') AS \"Value\"").SingleAsync();
        async Task Reset(){await using var other=fixture.CreateContext();await other.Database.ExecuteSqlRawAsync(regression?"SELECT setval('cerberus.server_sequence',1,false)":"SELECT setval('cerberus.server_sequence',9007199254740991,true)");}
        try{var store=parent?new FolderMoveStore(new ProfileSetup.Factory(fixture,new BeforeParent(Reset))):Store();if(!parent)await Reset();Assert.Equal(regression?"persistence_unavailable":"revision_conflict",(await store.MoveAsync(new(s.Actor,s.Verifier,target.PublicId,1,to.PublicId),default)).Error);Assert.Equal(before,await Snapshot(s));}finally{await db.Database.ExecuteSqlInterpolatedAsync($"SELECT setval('cerberus.server_sequence',{previous},true)");}
    }

