        Assert.Equal(error,(await new FolderMoveStore(new ProfileSetup.Factory(fixture,hook)).MoveAsync(new(s.Actor,s.Verifier,target.PublicId,1,to.PublicId),default)).Error);Assert.Equal(Bytes(target),Bytes(await Row(target.Id)));Assert.Equal(Bytes(from),Bytes(await FolderRow(from.Id)));Assert.Equal(Bytes(to),Bytes(await FolderRow(to.Id)));
    }

    private FolderMoveStore Store()=>new(fixture);
    private Task<VaultResult<FolderMoveDetails>> Move(ProfileSetup.State s,VaultFolder target,Guid? destination,long expected=1)=>Store().MoveAsync(new(s.Actor,s.Verifier,target.PublicId,expected,destination),default);
    private async Task Success(VaultFolder before,VaultFolder? destination,VaultFolder? from,VaultFolder? to,VaultResult<FolderMoveDetails> result)
    {
        Assert.Null(result.Error);var d=Assert.IsType<FolderMoveDetails>(result.Data);Assert.Equal(before.PublicId,d.FolderId);Assert.Equal(destination?.PublicId,d.ParentFolderId);Assert.Equal(before.Revision+1,d.Revision);Assert.True(d.ServerSequence>before.ServerSequence);Assert.InRange(d.ServerSequence,1,ProtocolBinary.MaxInteger);
        var row=await Row(before.Id);Assert.Equal(destination?.Id,row.ParentFolderId);Assert.Equal(before.Envelope,row.Envelope);Assert.Equal(before.EditedAt,row.EditedAt);Assert.Equal(before.AccountId,row.AccountId);Assert.Equal(d.Revision,row.Revision);Assert.Equal(d.ServerSequence,row.ServerSequence);Assert.NotEqual(before.ConcurrencyStamp,row.ConcurrencyStamp);Assert.Null(row.DeletedAt);Assert.Null(row.PurgeAt);
        foreach(var parent in new[]{from,to}.OfType<VaultFolder>().DistinctBy(x=>x.Id)){
            var current=await Row(parent.Id);var changed=before.ParentFolderId!=destination?.Id && (parent.Id==before.ParentFolderId || parent.Id==destination?.Id);Assert.Equal(parent.Revision+(changed?1:0),current.Revision);if(changed){Assert.True(current.ServerSequence>parent.ServerSequence);Assert.InRange(current.ServerSequence,1,ProtocolBinary.MaxInteger);Assert.NotEqual(parent.ConcurrencyStamp,current.ConcurrencyStamp);}else{Assert.Equal(parent.ServerSequence,current.ServerSequence);Assert.Equal(parent.ConcurrencyStamp,current.ConcurrencyStamp);}Assert.Equal(parent.Envelope,current.Envelope);Assert.Equal(parent.EditedAt,current.EditedAt);Assert.Equal(parent.ParentFolderId,current.ParentFolderId);Assert.Equal(parent.PurgeAt,current.PurgeAt);Assert.Equal(parent.DeletedAt,current.DeletedAt);
        }
        await using var db=fixture.CreateContext();Assert.False(await db.TrashEntries.AnyAsync(x=>x.ResourceKind=="folder" && x.ResourceId==before.PublicId));
    }
