    {private void Check(DbCommand c){if(c.CommandText.Contains("cerberus."+table)&&c.CommandText.Contains("FOR "))reached.TrySetResult();}public override ValueTask<InterceptionResult<int>> NonQueryExecutingAsync(DbCommand c,CommandEventData d,InterceptionResult<int> r,CancellationToken ct=default){Check(c);return ValueTask.FromResult(r);}public override ValueTask<InterceptionResult<DbDataReader>> ReaderExecutingAsync(DbCommand c,CommandEventData d,InterceptionResult<DbDataReader> r,CancellationToken ct=default){Check(c);return ValueTask.FromResult(r);}}
    private sealed class Capture(PostgresFixture fixture,bool analyze=false):DbCommandInterceptor
    {
        public List<string> Locks{get;}=[];public List<long[]> FolderIds{get;}=[];public List<long[]> RecordIds{get;}=[];public string? Plan{get;private set;}
        private void Note(DbCommand c){if(c.CommandText.Contains("FOR UPDATE")||c.CommandText.Contains("FOR NO KEY UPDATE")||c.CommandText.Contains("FOR SHARE")){Locks.Add(c.CommandText);if(c.CommandText.Contains("FROM cerberus.folder")&&c.CommandText.Contains("FOR UPDATE"))FolderIds.Add(c.Parameters.Cast<NpgsqlParameter>().Select(x=>x.Value).OfType<long[]>().Single());if(c.CommandText.Contains("FROM cerberus.record")&&c.CommandText.Contains("FOR UPDATE"))RecordIds.Add(c.Parameters.Cast<NpgsqlParameter>().Select(x=>x.Value).OfType<long[]>().Single());}}
        public override ValueTask<InterceptionResult<int>> NonQueryExecutingAsync(DbCommand c,CommandEventData d,InterceptionResult<int> r,CancellationToken ct=default){Note(c);return ValueTask.FromResult(r);}
        public override async ValueTask<InterceptionResult<DbDataReader>> ReaderExecutingAsync(DbCommand c,CommandEventData d,InterceptionResult<DbDataReader> r,CancellationToken ct=default){Note(c);if(analyze&&Plan is null&&c.CommandText.StartsWith("WITH RECURSIVE")){await using var db=fixture.CreateContext();await db.Database.OpenConnectionAsync(ct);await using var cmd=db.Database.GetDbConnection().CreateCommand();cmd.CommandText="EXPLAIN (ANALYZE, FORMAT JSON) "+c.CommandText;foreach(var p in c.Parameters.Cast<NpgsqlParameter>())cmd.Parameters.Add(p.Clone());Plan=(string)(await cmd.ExecuteScalarAsync(ct))!;await System.IO.File.WriteAllTextAsync("/tmp/cerberus-uc28-explain.json",Plan,ct);}return r;}
    }
    private static IEnumerable<JsonElement> Nodes(JsonElement n){yield return n;if(n.TryGetProperty("Plans",out var ps))foreach(var p in ps.EnumerateArray())foreach(var x in Nodes(p))yield return x;}
